// === BLOCK 2: PRO CODER BOT LOGIC (BRAIN) ===
webview.addJavascriptInterface(new Object() {
    @android.webkit.JavascriptInterface
    public void logAction(final String action) {
        if (isRecording[0]) { actionList.add(action); }
    }
}, "BotRecorder");

final String injectJs = "javascript:(function(){ " +
    "if(window.axiomRec) return; window.axiomRec = true; " +

    // Pro Element Finder (যেকোনো সাইটের এলিমেন্ট নিখুঁতভাবে চেনার জন্য)
    "window.getSel = function(el) { " +
    "  if(el.id) return '#' + el.id; " +
    "  if(el.name) return el.tagName.toLowerCase() + '[name=\"' + el.name + '\"]'; " +
    "  if(el.placeholder) return el.tagName.toLowerCase() + '[placeholder=\"' + el.placeholder + '\"]'; " +
    "  if(el.className && typeof el.className === 'string') { " +
    "    let c = el.className.trim().split(/\\s+/).join('.'); " +
    "    if(c) return el.tagName.toLowerCase() + '.' + c; " +
    "  } return el.tagName.toLowerCase(); " +
    "}; " +

    // ১. Click Action (মাউস ডাউন ইভেন্ট)
    "document.addEventListener('mousedown', function(e){ " +
    "  if(!window.isRecordingActive) return; " +
    "  let sel = window.getSel(e.target); " +
    "  let code = '    await sleep(1000);\\n    { let el = document.querySelector(\"' + sel + '\"); if(el) el.click(); }'; " +
    "  BotRecorder.logAction(code); " +
    "}, true); " +

    // ২. Typing Action (Debounce লজিক সহ - টাইপ শেষে একবারই সেভ হবে)
    "document.addEventListener('input', function(e){ " +
    "  if(!window.isRecordingActive) return; " +
    "  let sel = window.getSel(e.target); " +
    "  let val = e.target.value.replace(/'/g, \"\\\\'\"); " + // Single Quote ফিক্স
    "  clearTimeout(window.tyT); " +
    "  window.tyT = setTimeout(() => { " +
    "    let code = '    await sleep(1000);\\n    { let el = document.querySelector(\"' + sel + '\"); if(el) { el.focus(); el.value = \\'' + val + '\\'; el.dispatchEvent(new Event(\"input\", {bubbles:true})); el.dispatchEvent(new Event(\"change\", {bubbles:true})); } }'; " +
    "    BotRecorder.logAction(code); " +
    "  }, 800); " + // টাইপিং থামার ৮০০ মিলিসেকেন্ড পর কোড জেনারেট হবে
    "}, true); " +

    // ৩. Enter Key Action (ফর্ম সাবমিট বা সার্চ করার জন্য)
    "document.addEventListener('keydown', function(e){ " +
    "  if(!window.isRecordingActive) return; " +
    "  let sel = window.getSel(e.target); " +
    "  if(e.key === 'Enter'){ " +
    "    let code = '    await sleep(800);\\n    { let el = document.querySelector(\"' + sel + '\"); if(el) { el.dispatchEvent(new KeyboardEvent(\"keydown\", {bubbles:true, key:\"Enter\", keyCode:13})); if(el.form) el.form.submit(); } }'; " +
    "    BotRecorder.logAction(code); " +
    "  } " +
    "}, true); " +

    // ৪. Scroll Action (স্মুথ স্ক্রোলিং রেকর্ড)
    "window.addEventListener('scroll', function(){ " +
    "  if(!window.isRecordingActive) return; " +
    "  clearTimeout(window.scT); " +
    "  window.scT = setTimeout(() => { " +
    "    let code = '    await sleep(1000);\\n    window.scrollTo({top: ' + Math.round(window.scrollY) + ', behavior: \"smooth\"});'; " +
    "    BotRecorder.logAction(code); " +
    "  }, 1000); " +
    "}, true); " +
"})();";

webview.setWebViewClient(new android.webkit.WebViewClient() {
    @Override
    public void onPageFinished(android.webkit.WebView view, String url) {
        view.loadUrl(injectJs);
        if (isRecording[0]) view.loadUrl("javascript:window.isRecordingActive=true;");
    }
});

// Initial Page Load
webview.loadUrl("https://www.google.com");
